"use client";

import { useState } from "react";
import { useCart } from "@/lib/cart";
import { formatUGX } from "@/lib/menu-data";

export function CartDrawer() {
  const { isOpen, closeCart, lines, setQty, totalPrice, whatsappHref } =
    useCart();
  const [name, setName] = useState("");
  const [location, setLocation] = useState("");

  return (
    <>
      <div
        className={`fixed inset-0 z-50 bg-basil-deep/50 transition-opacity ${
          isOpen ? "opacity-100" : "pointer-events-none opacity-0"
        }`}
        onClick={closeCart}
      />
      <aside
        className={`fixed right-0 top-0 z-50 flex h-full w-full max-w-md flex-col bg-herb-white text-charcoal shadow-2xl transition-transform ${
          isOpen ? "translate-x-0" : "translate-x-full"
        }`}
        aria-hidden={!isOpen}
      >
        <div className="flex items-center justify-between border-b border-line px-6 py-5">
          <h2 className="font-display text-2xl">Your order</h2>
          <button
            onClick={closeCart}
            aria-label="Close cart"
            className="text-charcoal/60 hover:text-charcoal"
          >
            ✕
          </button>
        </div>

        <div className="flex-1 overflow-y-auto px-6 py-4">
          {lines.length === 0 ? (
            <p className="mt-10 text-center text-sm text-charcoal/50">
              Nothing here yet — add a meal plan to get started.
            </p>
          ) : (
            <ul className="divide-y divide-line">
              {lines.map((line) => (
                <li
                  key={`${line.planId}-${line.duration}`}
                  className="flex items-center justify-between py-4"
                >
                  <div>
                    <p className="font-medium">{line.planName}</p>
                    <p className="text-xs capitalize text-charcoal/50">
                      {line.duration} · UGX {formatUGX(line.unitPrice)}
                    </p>
                  </div>
                  <div className="flex items-center gap-3">
                    <button
                      onClick={() =>
                        setQty(line.planId, line.duration, line.qty - 1)
                      }
                      className="h-7 w-7 rounded-full border border-line text-sm"
                      aria-label={`Reduce ${line.planName}`}
                    >
                      −
                    </button>
                    <span className="w-4 text-center text-sm">
                      {line.qty}
                    </span>
                    <button
                      onClick={() =>
                        setQty(line.planId, line.duration, line.qty + 1)
                      }
                      className="h-7 w-7 rounded-full border border-line text-sm"
                      aria-label={`Increase ${line.planName}`}
                    >
                      +
                    </button>
                  </div>
                </li>
              ))}
            </ul>
          )}
        </div>

        {lines.length > 0 && (
          <div className="border-t border-line px-6 py-5">
            <div className="space-y-3">
              <input
                value={name}
                onChange={(e) => setName(e.target.value)}
                placeholder="Your name"
                className="w-full rounded-lg border border-line bg-white px-3 py-2 text-sm outline-none focus:border-zest"
              />
              <input
                value={location}
                onChange={(e) => setLocation(e.target.value)}
                placeholder="Delivery location"
                className="w-full rounded-lg border border-line bg-white px-3 py-2 text-sm outline-none focus:border-zest"
              />
            </div>

            <div className="mt-4 flex items-center justify-between font-display text-xl">
              <span>Total</span>
              <span>UGX {formatUGX(totalPrice)}</span>
            </div>

            <a
              href={whatsappHref({ name, location })}
              target="_blank"
              rel="noopener noreferrer"
              className="mt-4 block rounded-full bg-zest py-3 text-center text-sm font-medium text-basil transition-transform hover:-translate-y-0.5"
            >
              Send order on WhatsApp
            </a>
            <p className="mt-3 text-center text-xs text-charcoal/50">
              We&rsquo;ll confirm your order and payment on WhatsApp.
            </p>
          </div>
        )}
      </aside>
    </>
  );
}
