"use client";

import { useState } from "react";
import { mealPlans, formatUGX, type Duration } from "@/lib/menu-data";
import { useCart } from "@/lib/cart";

export function MealPlans() {
  return (
    <section id="menu" className="bg-basil py-24 text-bone">
      <div className="mx-auto max-w-6xl px-6">
        <div className="max-w-xl">
          <p className="font-display text-lg italic text-zest">Discover</p>
          <h2 className="mt-2 font-display text-4xl leading-tight md:text-5xl">
            Our meal plans
          </h2>
          <p className="mt-6 text-bone/70">
            Choose weekly if you&rsquo;re trying us out, or monthly once
            lunch stops being a decision you make every day. Delivery and
            meal-plan design are already built into every price.
          </p>
        </div>

        <div className="mt-14 grid gap-6 sm:grid-cols-2 lg:grid-cols-3">
          {mealPlans.map((plan) => (
            <PlanCard key={plan.id} plan={plan} />
          ))}
        </div>

        <p className="mt-10 text-sm text-bone/50">
          Payments accepted by Mobile Money, cash, or bank deposit — you can
          settle up once your order is confirmed on WhatsApp.
        </p>
      </div>
    </section>
  );
}

function PlanCard({
  plan,
}: {
  plan: (typeof mealPlans)[number];
}) {
  const [duration, setDuration] = useState<Duration>("weekly");
  const { addLine } = useCart();

  const price = duration === "weekly" ? plan.weeklyPrice : plan.monthlyPrice;

  return (
    <div
      className={`flex flex-col rounded-3xl border p-7 ${
        plan.featured
          ? "border-zest bg-[#1c2e22]"
          : "border-bone/15 bg-[#1a2a20]"
      }`}
    >
      <h3 className="font-display text-2xl">{plan.name}</h3>
      <p className="mt-2 text-sm text-bone/60">{plan.tagline}</p>

      <div className="mt-6 inline-flex w-fit rounded-full border border-bone/20 p-1 text-xs">
        {(["weekly", "monthly"] as Duration[]).map((d) => (
          <button
            key={d}
            onClick={() => setDuration(d)}
            className={`rounded-full px-3 py-1.5 capitalize transition-colors ${
              duration === d
                ? "bg-zest text-basil"
                : "text-bone/70 hover:text-bone"
            }`}
          >
            {d}
          </button>
        ))}
      </div>

      <p className="mt-6 font-display text-3xl">
        UGX {formatUGX(price)}
        <span className="ml-1 text-sm font-normal text-bone/50">
          / {duration === "weekly" ? "week" : "month"}
        </span>
      </p>

      <button
        onClick={() =>
          addLine({
            planId: plan.id,
            planName: plan.name,
            duration,
            unitPrice: price,
          })
        }
        className="mt-6 rounded-full bg-zest py-3 text-sm font-medium text-basil transition-transform hover:-translate-y-0.5"
      >
        Add to order
      </button>
    </div>
  );
}
